(function(){
  'use strict';
  const style=document.createElement('style');
  style.textContent='body[data-petro-case] .judge{display:grid;grid-template-columns:repeat(4,minmax(0,1fr))}body[data-petro-case] .judge .jl{font-size:10px}body[data-petro-case] .judge .jd{font-size:12px}body[data-petro-case] .judge .jc{padding:18px}@media(max-width:900px){body[data-petro-case] .judge{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:480px){body[data-petro-case] .judge .jc{padding:12px}body[data-petro-case] .judge .jv{font-size:13px}}';
  document.head.append(style);
  function apply(){
    const route=location.hash.match(/^#\/scene\/(p[1-4])(?:\?|$)/);
    if(!route||!window.Cases){delete document.body.dataset.petroCase;return;}
    const id=new URLSearchParams(location.hash.split('?')[1]||'').get('case');
    const cases=Cases.bySceneAll(route[1]);
    const current=cases.find(c=>c.id===id)||cases[0];
    if(!current)return;
    const head=document.querySelector('.detail-head');
    if(!head)return;
    document.body.dataset.petroCase=current.id;
    document.querySelectorAll('.case-switch').forEach(el=>el.remove());
    head.querySelectorAll('.dh-kicker>span.tag').forEach(el=>{
      if(/^共\s*\d+\s*个案例$/.test(el.textContent.trim()))el.remove();
    });
    // Secondary cases keep their own title when opened from the case library.
    const title=head.querySelector('.dh-title');
    if(title&&title.textContent!==current.title)title.textContent=current.title;
    const crumb=document.querySelector('.crumb .cur');
    if(crumb&&crumb.textContent!==current.title)crumb.textContent=current.title;
    const difficulty=current.tabs.background.judge?.find(c=>c.label==='难度')?.value;
    const tag=head.querySelector('.dh-tags .dtag');
    if(tag&&difficulty){tag.dataset.d=difficulty;if(tag.textContent!=='难度 '+difficulty)tag.textContent='难度 '+difficulty;}
    if(current.tabs.background){
      const sub=head.querySelector('.dh-sub');
      const scope=current.pageIntro||current.tabs.background.lede;
      if(sub&&scope&&sub.textContent!==scope)sub.textContent=scope;
    }
    const pageTitle=current.title+' · 智能化可能性地图';
    if(document.title!==pageTitle)document.title=pageTitle;
  }
  let queued=false;
  new MutationObserver(()=>{if(!queued){queued=true;queueMicrotask(()=>{queued=false;apply()})}})
    .observe(document.documentElement,{childList:true,subtree:true});
  window.addEventListener('hashchange',apply);
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',apply);
  else apply();
})();
